window.HUD_BUNDLE=["(function(root){\nfunction parseSheets(sheets){\n const result=[];\n for(const [sheet,rows] of Object.entries(sheets)){\n  const hi=rows.findIndex(r=>String(r[0]||'').trim().toLowerCase()==='item');\n  if(hi\u003c0)continue;\n  const headers=rows[hi];\n  for(const row of rows.slice(hi+1)){\n   const name=String(row[0]||'').trim();\n   if(!name)continue;\n   const points=[];let missing=0,invalid=0;\n   for(let c=1;c\u003cheaders.length;c++){\n    if(headers[c]==null||headers[c]==='')continue;\n    const raw=row[c];\n    if(raw==null||raw===''){missing++;continue;}\n    const v=typeof raw==='number'?raw:(typeof raw==='string'&&/^[+-]?(?:\\d+\\.?\\d*|\\.\\d+)(?:e[+-]?\\d+)?$/i.test(raw.trim())?Number(raw):NaN);\n    if(Number.isFinite(v))points.push({id:String(headers[c]),v});else invalid++;\n   }\n   if(!points.length)continue;\n   const unit=(name.match(/\\(([^()]*)\\)\\s*$/)||[])[1]||'';\n   let lo=null,hi=null,source='未提供客户限值',note='仅统计，待补充项目要求';\n   if(/Image Size/i.test(name)&&unit==='%'){lo=-5;hi=5;source='表内限值 ±5%';note='本表项目筛查；全局指标不能替代所有相邻网格点的 ±5% 验证';}\n   if(/Global Mag/i.test(name)&&unit==='%'){lo=95;hi=105;source='表内 global magnification ±5%';note='按 100% 为标称值，范围 95%～105%；请确认客户定义';}\n   if(/Rotation/i.test(name)&&unit==='°'){lo=-1;hi=1;source='表内限值 ±1°';note='当前为平均旋转，不能证明所有水平线段均满足 ±1°';}\n   if(/Ghost/i.test(name)&&unit==='mm'){let limit=sheet==='EB_N'?1:(sheet==='EB_H'||sheet==='EB_L'?1.5:null);if(limit!==null){lo=-limit;hi=limit;source='工作表重影限值 ±'+limit+' mm';note='按表内双向限值筛查。PDF 的 Tall 向下 / Short 向上为方向性要求；本表 Avg 不足以核验逐点最差重影、方向及三眼位最终判定';}}\n   result.push({key:sheet+'|'+name,sheet,name,unit,points,missing,invalid,lo,hi,source,note});\n  }\n }\n return result;\n}\nfunction stats(item){const a=item.points.map(p=>p.v),n=a.length,mean=a.reduce((s,x)=>s+x,0)/n,sd=n>1?Math.sqrt(a.reduce((s,x)=>s+(x-mean)**2,0)/(n-1)):0;const specified=item.lo!==null||item.hi!==null;const bad=item.points.filter(p=>(item.lo!==null&&p.v\u003citem.lo)||(item.hi!==null&&p.v>item.hi));return{n,mean,sd,min:Math.min(...a),max:Math.max(...a),specified,bad,pass:specified?(n-bad.length)/n:null};}\nroot.HUD={parseSheets,stats};if(typeof module!=='undefined')module.exports=root.HUD;\n})(globalThis);\n", "let items=[],filename='';\nconst $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&\u003c>\"']/g,c=>({'&':'&amp;','\u003c':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])),fmt=n=>Number.isFinite(n)?Number(n.toFixed(4)).toString():'—';\nfunction download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);}\nfunction load(sheets,name){const parsed=HUD.parseSheets(sheets);if(!parsed.length)throw Error('未找到测量数据。请使用首列 Item、首行为样品编号、每行一个测量项目的表格。');items=parsed;filename=name;$('#filename').textContent=name;$('#error').textContent='';$('#sheet').innerHTML='\u003coption value=\"\">全部眼位\u003c/option>'+[...new Set(items.map(x=>x.sheet))].map(s=>`\u003coption>${esc(s)}\u003c/option>`).join('');$('#search').value='';$('#status').value='';for(const id of ['csv','report','print'])$('#'+id).disabled=false;render();}\nfunction chart(item,kind){\n const st=HUD.stats(item),W=640,H=250,L=60,R=22,T=28,B=42,w=W-L-R,h=H-T-B;\n let min=Math.min(st.min,...[item.lo,item.hi].filter(x=>x!==null)),max=Math.max(st.max,...[item.lo,item.hi].filter(x=>x!==null));let pad=(max-min)*.12||Math.max(Math.abs(max)*.1,.1);min-=pad;max+=pad;\n const y=v=>T+h-(v-min)/(max-min)*h,x=i=>L+(st.n===1?w/2:i/(st.n-1)*w);\n let s=`\u003csvg class=\"chart\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"${esc(item.sheet+' '+item.name)}\">\u003crect width=\"640\" height=\"250\" fill=\"white\"/>\u003ctext x=\"${L}\" y=\"16\">${esc(item.unit)} · ${kind==='trend'?'样品趋势':'分布频数'}\u003c/text>`;\n if(kind==='trend'){\n  if(item.lo!==null&&item.hi!==null)s+=`\u003crect x=\"${L}\" y=\"${y(item.hi)}\" width=\"${w}\" height=\"${y(item.lo)-y(item.hi)}\" fill=\"#edf7f2\"/>`;\n  for(let i=0;i\u003c=4;i++){const v=min+(max-min)*i/4;s+=`\u003cpath d=\"M${L},${y(v)}H${W-R}\" stroke=\"#e3eaf1\"/>\u003ctext x=\"${L-8}\" y=\"${y(v)+4}\" text-anchor=\"end\">${fmt(v)}\u003c/text>`;}\n  for(const [v,label]of [[item.lo,'LSL'],[item.hi,'USL']])if(v!==null)s+=`\u003cpath class=\"limit\" stroke=\"#d73d4b\" stroke-dasharray=\"5 4\" d=\"M${L},${y(v)}H${W-R}\"/>\u003ctext x=\"${W-R}\" y=\"${y(v)-5}\" text-anchor=\"end\" style=\"fill:#d73d4b\">${label} ${fmt(v)}\u003c/text>`;\n  s+=`\u003cpolyline fill=\"none\" stroke=\"#1676bf\" stroke-width=\"2\" points=\"${item.points.map((p,i)=>x(i)+','+y(p.v)).join(' ')}\"/>`;\n  item.points.forEach((p,i)=>{const bad=(item.lo!==null&&p.v\u003citem.lo)||(item.hi!==null&&p.v>item.hi);s+=`\u003ccircle cx=\"${x(i)}\" cy=\"${y(p.v)}\" r=\"${st.n>100?2:4}\" fill=\"${bad?'#d73d4b':'#1676bf'}\">\u003ctitle>样品 ${esc(p.id)}：${p.v} ${esc(item.unit)}${bad?' 超差':''}\u003c/title>\u003c/circle>`;if(i===0||i===st.n-1||i%Math.max(1,Math.ceil(st.n/8))===0)s+=`\u003ctext x=\"${x(i)}\" y=\"${H-21}\" text-anchor=\"middle\">${esc(p.id)}\u003c/text>`;});\n }else{\n  const count=Math.max(3,Math.min(14,Math.ceil(Math.sqrt(st.n)))),bins=Array(count).fill(0),bw=(max-min)/count;\n  item.points.forEach(p=>bins[Math.min(count-1,Math.floor((p.v-min)/bw))]++);const top=Math.max(...bins),xx=v=>L+(v-min)/(max-min)*w;\n  bins.forEach((n,i)=>{const bh=n/top*h;s+=`\u003crect x=\"${L+i*w/count+2}\" y=\"${T+h-bh}\" width=\"${w/count-4}\" height=\"${bh}\" fill=\"#438fc5\">\u003ctitle>${fmt(min+i*bw)}～${fmt(min+(i+1)*bw)}：${n} 件\u003c/title>\u003c/rect>\u003ctext x=\"${L+(i+.5)*w/count}\" y=\"${T+h-bh-5}\" text-anchor=\"middle\">${n}\u003c/text>`;});\n  for(let i=0;i\u003c=4;i++){const v=min+(max-min)*i/4;s+=`\u003ctext x=\"${xx(v)}\" y=\"${H-22}\" text-anchor=\"middle\">${fmt(v)}\u003c/text>`;}\n  for(const [v,label]of [[item.lo,'LSL'],[item.hi,'USL']])if(v!==null)s+=`\u003cpath stroke=\"#d73d4b\" stroke-dasharray=\"5 4\" d=\"M${xx(v)},${T}V${T+h}\"/>\u003ctext x=\"${xx(v)}\" y=\"${T-6}\" text-anchor=\"middle\">${label} ${v}\u003c/text>`;\n }\n return s+`\u003cpath d=\"M${L},${T}V${T+h}H${W-R}\" fill=\"none\" stroke=\"#aab9c9\"/>\u003c/svg>`;\n}\nfunction render(){\n const sampleIds=new Set(items.flatMap(x=>x.points.map(p=>p.id))),specified=items.filter(x=>HUD.stats(x).specified),bad=specified.filter(x=>HUD.stats(x).bad.length);\n $('#metrics').innerHTML=[['有效样品编号',sampleIds.size],['测量项目',items.length],['超差项目 / 已设限值',bad.length+' / '+specified.length],['待补限值项目',items.length-specified.length]].map(([k,v])=>`\u003cdiv class=\"metric\">\u003cspan>${k}\u003c/span>\u003cstrong>${v}\u003c/strong>\u003c/div>`).join('');\n const q=$('#search').value.toLowerCase().trim().replace('重影','ghost').replace('旋转','rotation').replace('尺寸','image size').replace('平移','translation').replace('畸变','distortion').replace('梯形','trapezoid'),status=$('#status').value;\n const visible=items.filter(x=>{const s=HUD.stats(x);return (!$('#sheet').value||x.sheet===$('#sheet').value)&&x.name.toLowerCase().includes(q)&&(!status||(status==='bad'&&s.bad.length)||(status==='unknown'&&!s.specified)||(status==='ok'&&s.specified&&!s.bad.length));});\n $('#empty').classList.toggle('hidden',items.length>0);$('#count').textContent=`显示 ${visible.length} 项`;$('#cards').innerHTML=visible.map(item=>{const i=items.indexOf(item),s=HUD.stats(item);return `\u003carticle class=\"card\" data-i=\"${i}\">\u003cdiv class=\"cardtop\">\u003cdiv>\u003cspan class=\"muted\">${esc(item.sheet)} · ${item.sheet==='EB_N'?'标准眼位':item.sheet==='EB_H'?'高眼位':item.sheet==='EB_L'?'低眼位':'其他眼位'}\u003c/span>\u003ch3>${esc(item.name)}\u003c/h3>\u003c/div>\u003cspan class=\"badge ${!s.specified?'':s.bad.length?'bad':'ok'}\">${!s.specified?'待设限值':s.bad.length?'超差 '+s.bad.length+' 件':'本项限值内'}\u003c/span>\u003c/div>\u003cdiv class=\"stats\">${[['有效 N',s.n],['均值',fmt(s.mean)],['最小 / 最大',fmt(s.min)+' / '+fmt(s.max)],['样本标准差',fmt(s.sd)],['本项合格率',s.pass===null?'未判定':(s.pass*100).toFixed(1)+'%']].map(([k,v])=>`\u003cspan>${k}\u003cb>${v}\u003c/b>\u003c/span>`).join('')}\u003c/div>${chart(item,$('#view').value)}\u003cdiv class=\"limits\">\u003clabel>下限 \u003cinput aria-label=\"下限\" class=\"lo\" type=\"number\" step=\"any\" value=\"${item.lo??''}\">\u003c/label>\u003clabel>上限 \u003cinput aria-label=\"上限\" class=\"hi\" type=\"number\" step=\"any\" value=\"${item.hi??''}\">\u003c/label>\u003cbutton class=\"secondary apply\">应用\u003c/button>\u003cspan>${esc(item.unit)}\u003c/span>\u003c/div>\u003cp class=\"note\">依据：${esc(item.source)}\u003c/p>\u003cp class=\"note\">${esc(item.note)}\u003c/p>\u003cp class=\"note\">空白预留单元格 ${item.missing} 个未计入；非数值 ${item.invalid} 个未计入。横轴按表中顺序排列，连线不代表时间过程。\u003c/p>\u003cdiv class=\"actions\">\u003cbutton class=\"secondary svg\">导出 SVG 图表\u003c/button>\u003cbutton class=\"secondary png\">导出 PNG 图片\u003c/button>\u003c/div>\u003cdetails>\u003csummary>样品数据 / 超差明细（${s.bad.length}）\u003c/summary>\u003cdiv class=\"scroll\">\u003ctable>\u003cthead>\u003ctr>\u003cth>样品\u003c/th>\u003cth>测量值 ${esc(item.unit)}\u003c/th>\u003cth>判定\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>${item.points.map(p=>{let b=(item.lo!==null&&p.v\u003citem.lo)||(item.hi!==null&&p.v>item.hi);return `\u003ctr>\u003ctd>${esc(p.id)}\u003c/td>\u003ctd>${p.v}\u003c/td>\u003ctd style=\"color:${b?'#bd263a':'inherit'}\">${!s.specified?'未判定':b?'超差':'限值内'}\u003c/td>\u003c/tr>`;}).join('')}\u003c/tbody>\u003c/table>\u003c/div>\u003c/details>\u003c/article>`;}).join('');\n}\n$('#file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;$('#filename').textContent='正在读取…';const book=XLSX.read(await file.arrayBuffer(),{type:'array'}),sheets={};book.SheetNames.forEach(n=>{sheets[n]=XLSX.utils.sheet_to_json(book.Sheets[n],{header:1,defval:null,raw:true,blankrows:false});});load(sheets,file.name);}catch(err){$('#error').textContent='读取失败：'+err.message;$('#filename').textContent=filename||'尚未加载文件';}finally{e.target.value='';}};\n$('#demo').onclick=()=>load(window.HUD_DEMO,'L232 HUD Inspective dates 20261110.xlsx');\nfor(const s of ['sheet','status','view'])$('#'+s).onchange=render;$('#search').oninput=render;\n$('#cards').onclick=async e=>{const card=e.target.closest('.card');if(!card)return;const item=items[Number(card.dataset.i)];if(e.target.closest('.apply')){let lo=card.querySelector('.lo').value,hi=card.querySelector('.hi').value;lo=lo===''?null:Number(lo);hi=hi===''?null:Number(hi);if((lo!==null&&!Number.isFinite(lo))||(hi!==null&&!Number.isFinite(hi))||(lo!==null&&hi!==null&&lo>hi)){alert('请输入有效限值，且下限不能大于上限');return;}item.lo=lo;item.hi=hi;item.source='用户手动设置（需核对客户批准限值）';render();}\n if(e.target.closest('.svg')||e.target.closest('.png')){const svg=chart(item,$('#view').value),blob=new Blob([svg],{type:'image/svg+xml;charset=utf-8'}),name=(item.sheet+'_'+item.name).replace(/[\\\\/:*?\"\u003c>|]/g,'_');if(e.target.closest('.svg'))download(blob,name+'.svg');else{const url=URL.createObjectURL(blob),img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=1920;c.height=750;c.getContext('2d').drawImage(img,0,0,1920,750);c.toBlob(b=>download(b,name+'.png'));URL.revokeObjectURL(url);};img.src=url;}}};\nfunction csvCell(v){let t=String(v??'');if(/^[=+@-]/.test(t)&&!Number.isFinite(Number(t)))t=\"'\"+t;return '\"'+t.replace(/\"/g,'\"\"')+'\"';}\n$('#csv').onclick=()=>{const rows=[['文件','眼位','项目','单位','下限','上限','N','均值','最小','最大','样本标准差','超差数','合格率','超差样品','限值依据','判定限制']];items.forEach(x=>{const s=HUD.stats(x);rows.push([filename,x.sheet,x.name,x.unit,x.lo,x.hi,s.n,s.mean,s.min,s.max,s.sd,s.specified?s.bad.length:'未判定',s.pass===null?'未判定':(s.pass*100).toFixed(2)+'%',s.bad.map(p=>p.id+':'+p.v).join(';'),x.source,x.note]);});download(new Blob(['\\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\\r\\n')],{type:'text/csv;charset=utf-8'}),'HUD分析汇总.csv');};\n$('#print').onclick=()=>window.print();\n$('#report').onclick=()=>{const doc=document.documentElement.cloneNode(true);doc.querySelectorAll('script').forEach(s=>s.remove());const state=JSON.stringify({items,filename}).replace(/\u003c/g,'\\\\u003c');const boot=document.createElement('script');boot.textContent='window.HUD_REPORT='+state+';window.HUD_BUNDLE='+JSON.stringify(window.HUD_BUNDLE).replace(/\u003c/g,'\\\\u003c')+';';doc.querySelector('body').appendChild(boot);for(const source of window.HUD_BUNDLE){const s=document.createElement('script');s.textContent=source;doc.querySelector('body').appendChild(s);}download(new Blob(['\u003c!doctype html>'+doc.outerHTML],{type:'text/html;charset=utf-8'}),'HUD交互报告.html');};\nif(window.HUD_REPORT){items=window.HUD_REPORT.items;filename=window.HUD_REPORT.filename;$('#filename').textContent=filename;for(const id of ['csv','report','print'])$('#'+id).disabled=false;$('#demo').disabled=true;$('#file').disabled=true;render();}\n"];